<?php

namespace App\Http\Controllers\Api;

use App\Http\Controllers\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Hash;
use Illuminate\Support\Facades\Storage;
use Illuminate\Validation\Rule;

class TravelApiController extends Controller
{
    private function ok($data = [], int $status = 200) { return response()->json(['success'=>true,'data'=>$data], $status); }
    private function fail(string $message, int $status = 400) { return response()->json(['success'=>false,'message'=>$message], $status); }
    private function role(Request $r): string { return $r->user()->role ?? ''; }
    private function ownsTravel(Request $r, $travel): bool { return $travel && ($travel->user_id === $r->user()->id || in_array($this->role($r), ['ADMIN','SUPER_ADMIN','MANAGER','DEPARTMENT_HEAD','HRD'], true)); }

    public function register(Request $r) {
        $v=$r->validate(['name'=>'required|string|max:150','email'=>'required|email|unique:users,email','password'=>'required|string|min:8','departmentId'=>'required|exists:departments,id','positionId'=>'required|exists:positions,id']);
        $id=DB::table('users')->insertGetId(['name'=>$v['name'],'email'=>$v['email'],'password'=>Hash::make($v['password']),'department_id'=>$v['departmentId'],'position_id'=>$v['positionId'],'role'=>'EMPLOYEE','is_active'=>true,'created_at'=>now(),'updated_at'=>now()]);
        $u=\App\Models\User::findOrFail($id); $token=$u->createToken('api-token')->plainTextToken;
        return $this->ok(['user'=>$this->userData($u),'token'=>$token],201);
    }
    public function login(Request $r) {
        $v=$r->validate(['email'=>'required|email','password'=>'required|string']);
        $u=\App\Models\User::where('email',$v['email'])->where('is_active',true)->first();
        if(!$u || !Hash::check($v['password'],$u->password)) return $this->fail('Email atau password salah',401);
        return $this->ok(['user'=>$this->userData($u),'token'=>$u->createToken('api-token')->plainTextToken]);
    }
    public function me(Request $r) { return $this->ok(['user'=>$this->userData($r->user())]); }
    private function userData($u) { return ['id'=>$u->id,'name'=>$u->name,'email'=>$u->email,'role'=>$u->role,'departmentId'=>$u->department_id,'positionId'=>$u->position_id]; }

    public function usersIndex(Request $r) { $q=DB::table('users')->where('is_active',true); if($r->filled('role'))$q->where('role',$r->role); if($r->filled('departmentId'))$q->where('department_id',$r->departmentId); return $this->ok($q->get()); }
    public function userShow($id) { $u=DB::table('users')->where('id',$id)->where('is_active',true)->first(); return $u ? $this->ok($u) : $this->fail('User tidak ditemukan',404); }
    public function userUpdate(Request $r,$id) { $v=$r->validate(['name'=>'sometimes|required|string|max:150','departmentId'=>'sometimes|required|exists:departments,id','positionId'=>'sometimes|required|exists:positions,id']); $d=[]; foreach(['name'=>'name','departmentId'=>'department_id','positionId'=>'position_id'] as $a=>$b)if(array_key_exists($a,$v))$d[$b]=$v[$a];$d['updated_at']=now();DB::table('users')->where('id',$id)->update($d);return $this->ok(DB::table('users')->find($id)); }
    public function userRole(Request $r,$id) { $v=$r->validate(['role'=>['required',Rule::in(['EMPLOYEE','MANAGER','DEPARTMENT_HEAD','HRD','FINANCE','ADMIN','SUPER_ADMIN'])]]);DB::table('users')->where('id',$id)->update(['role'=>$v['role'],'updated_at'=>now()]);return $this->ok(DB::table('users')->find($id)); }
    public function userDeactivate($id) { DB::table('users')->where('id',$id)->update(['is_active'=>false,'updated_at'=>now()]);return $this->ok(['message'=>'User dinonaktifkan']); }

    private function masterIndex($table) { return $this->ok(DB::table($table)->orderBy('id')->get()); }
    private function masterCreate(Request $r,$table) { $v=$r->validate(['name'=>'required|string|max:150']);$id=DB::table($table)->insertGetId(['name'=>$v['name'],'created_at'=>now(),'updated_at'=>now()]);return $this->ok(DB::table($table)->find($id),201); }
    private function masterUpdate(Request $r,$table,$id) { $v=$r->validate(['name'=>'required|string|max:150']);DB::table($table)->where('id',$id)->update(['name'=>$v['name'],'updated_at'=>now()]);return $this->ok(DB::table($table)->find($id)); }
    private function masterDelete($table,$id) { DB::table($table)->where('id',$id)->delete();return $this->ok(['message'=>'Data dihapus']); }
    public function departmentsIndex(){return $this->masterIndex('departments');}
    public function departmentCreate(Request $r){return $this->masterCreate($r,'departments');}
    public function departmentUpdate(Request $r,$id){return $this->masterUpdate($r,'departments',$id);}
    public function departmentDelete($id){return $this->masterDelete('departments',$id);}
    public function positionsIndex(){return $this->masterIndex('positions');}
    public function positionCreate(Request $r){return $this->masterCreate($r,'positions');}
    public function positionUpdate(Request $r,$id){return $this->masterUpdate($r,'positions',$id);}
    public function positionDelete($id){return $this->masterDelete('positions',$id);}

    public function policiesIndex(){return $this->ok(DB::table('travel_policies')->get());}
    public function policyApplicable(Request $r){$v=$r->validate(['positionId'=>'required|integer','destinationTier'=>'required|string']);return $this->ok(DB::table('travel_policies')->where('position_id',$v['positionId'])->where('destination_tier',$v['destinationTier'])->where('is_active',true)->get());}
    public function policyCreate(Request $r){$v=$r->validate(['name'=>'required|string','positionId'=>'required|exists:positions,id','destinationTier'=>'required|string','max_budget'=>'required|numeric|min:0']);$id=DB::table('travel_policies')->insertGetId(['name'=>$v['name'],'position_id'=>$v['positionId'],'destination_tier'=>$v['destinationTier'],'max_budget'=>$v['max_budget'],'is_active'=>true,'created_at'=>now(),'updated_at'=>now()]);return $this->ok(DB::table('travel_policies')->find($id),201);}
    public function policyUpdate(Request $r,$id){$v=$r->validate(['name'=>'sometimes|string','positionId'=>'sometimes|exists:positions,id','destinationTier'=>'sometimes|string','max_budget'=>'sometimes|numeric|min:0','is_active'=>'sometimes|boolean']);$map=['name'=>'name','positionId'=>'position_id','destinationTier'=>'destination_tier','max_budget'=>'max_budget','is_active'=>'is_active'];$d=[];foreach($map as $a=>$b)if(isset($v[$a]))$d[$b]=$v[$a];$d['updated_at']=now();DB::table('travel_policies')->where('id',$id)->update($d);return $this->ok(DB::table('travel_policies')->find($id));}
    public function policyDelete($id){return $this->masterDelete('travel_policies',$id);}

    public function travelIndex(Request $r){$q=DB::table('travel_requests');if($this->role($r)==='EMPLOYEE')$q->where('user_id',$r->user()->id);if($r->filled('status'))$q->where('status',$r->status);if($r->filled('departmentId'))$q->where('department_id',$r->departmentId);return $this->ok($q->orderByDesc('created_at')->get());}
    public function travelCreate(Request $r){$v=$r->validate(['destination'=>'required|string|max:255','purpose'=>'required|string','startDate'=>'required|date','endDate'=>'required|date|after_or_equal:startDate','estimatedCost'=>'required|numeric|min:0','policyId'=>'required|exists:travel_policies,id']);$id=DB::table('travel_requests')->insertGetId(['user_id'=>$r->user()->id,'department_id'=>$r->user()->department_id,'destination'=>$v['destination'],'purpose'=>$v['purpose'],'start_date'=>$v['startDate'],'end_date'=>$v['endDate'],'estimated_cost'=>$v['estimatedCost'],'policy_id'=>$v['policyId'],'status'=>'DRAFT','created_at'=>now(),'updated_at'=>now()]);return $this->ok(DB::table('travel_requests')->find($id),201);}
    public function travelShow(Request $r,$id){$t=DB::table('travel_requests')->find($id);if(!$this->ownsTravel($r,$t))return $this->fail('Travel tidak ditemukan atau tidak memiliki akses',404);return $this->ok(['travel'=>$t,'approvals'=>DB::table('approvals')->where('travel_request_id',$id)->orderBy('level')->get()]);}
    public function travelUpdate(Request $r,$id){$t=DB::table('travel_requests')->find($id);if(!$t||$t->user_id!==$r->user()->id)return $this->fail('Tidak memiliki akses',403);if($t->status!=='DRAFT')return $this->fail('Hanya DRAFT yang dapat diedit',409);$v=$r->validate(['destination'=>'sometimes|string','purpose'=>'sometimes|string','startDate'=>'sometimes|date','endDate'=>'sometimes|date','estimatedCost'=>'sometimes|numeric|min:0','policyId'=>'sometimes|exists:travel_policies,id']);$map=['destination'=>'destination','purpose'=>'purpose','startDate'=>'start_date','endDate'=>'end_date','estimatedCost'=>'estimated_cost','policyId'=>'policy_id'];$d=[];foreach($map as $a=>$b)if(isset($v[$a]))$d[$b]=$v[$a];$d['updated_at']=now();DB::table('travel_requests')->where('id',$id)->update($d);return $this->ok(DB::table('travel_requests')->find($id));}
    public function travelDelete(Request $r,$id){$t=DB::table('travel_requests')->find($id);if(!$t||$t->user_id!==$r->user()->id)return $this->fail('Tidak memiliki akses',403);if($t->status!=='DRAFT')return $this->fail('Hanya DRAFT yang dapat dihapus',409);DB::table('travel_requests')->where('id',$id)->delete();return $this->ok(['message'=>'Draft dihapus']);}
    public function travelSubmit(Request $r,$id){$t=DB::table('travel_requests')->find($id);if(!$t||$t->user_id!==$r->user()->id)return $this->fail('Tidak memiliki akses',403);if($t->status!=='DRAFT')return $this->fail('Hanya DRAFT yang dapat disubmit',409);DB::transaction(function()use($t,$id){DB::table('travel_requests')->where('id',$id)->update(['status'=>'SUBMITTED','updated_at'=>now()]);$manager=DB::table('users')->where('department_id',$t->department_id)->where('role','MANAGER')->where('is_active',true)->first();DB::table('approvals')->insert(['travel_request_id'=>$id,'approver_id'=>$manager->id??null,'level'=>1,'status'=>'PENDING','note'=>null,'created_at'=>now(),'updated_at'=>now()]);});return $this->ok(DB::table('travel_requests')->find($id));}
    public function travelCancel(Request $r,$id){$t=DB::table('travel_requests')->find($id);if(!$t||$t->user_id!==$r->user()->id)return $this->fail('Tidak memiliki akses',403);if(in_array($t->status,['COMPLETED','CANCELLED'],true))return $this->fail('Travel tidak dapat dibatalkan',409);DB::transaction(function()use($id){DB::table('travel_requests')->where('id',$id)->update(['status'=>'CANCELLED','updated_at'=>now()]);DB::table('approvals')->where('travel_request_id',$id)->where('status','PENDING')->update(['status'=>'CANCELLED','updated_at'=>now()]);});return $this->ok(DB::table('travel_requests')->find($id));}
    public function documentUpload(Request $r,$id){$t=DB::table('travel_requests')->find($id);if(!$t||$t->user_id!==$r->user()->id)return $this->fail('Tidak memiliki akses',403);$r->validate(['file'=>'required|file|max:10240']);$path=$r->file('file')->store('travel-documents');$doc=DB::table('travel_documents')->insertGetId(['travel_request_id'=>$id,'uploaded_by'=>$r->user()->id,'path'=>$path,'original_name'=>$r->file('file')->getClientOriginalName(),'created_at'=>now(),'updated_at'=>now()]);return $this->ok(DB::table('travel_documents')->find($doc),201);}
    public function documentsIndex(Request $r,$id){$t=DB::table('travel_requests')->find($id);if(!$this->ownsTravel($r,$t))return $this->fail('Tidak memiliki akses',403);return $this->ok(DB::table('travel_documents')->where('travel_request_id',$id)->get());}
    public function documentDelete(Request $r,$docId){$d=DB::table('travel_documents')->find($docId);if(!$d)return $this->fail('Dokumen tidak ditemukan',404);$t=DB::table('travel_requests')->find($d->travel_request_id);if(!$t||$t->user_id!==$r->user()->id)return $this->fail('Tidak memiliki akses',403);Storage::delete($d->path);DB::table('travel_documents')->where('id',$docId)->delete();return $this->ok(['message'=>'Dokumen dihapus']);}

    public function bookingsIndex(Request $r,$travelId){$t=DB::table('travel_requests')->find($travelId);if(!$this->ownsTravel($r,$t))return $this->fail('Tidak memiliki akses',403);return $this->ok(DB::table('travel_bookings')->where('travel_request_id',$travelId)->get());}
    public function bookingCreate(Request $r,$travelId){$t=DB::table('travel_requests')->find($travelId);if(!$t||$t->status!=='APPROVED')return $this->fail('Travel harus berstatus APPROVED',409);$v=$r->validate(['provider'=>'required|string','bookingType'=>'required|in:FLIGHT,HOTEL,TRAIN,OTHER','reference'=>'nullable|string','cost'=>'required|numeric|min:0']);$id=DB::table('travel_bookings')->insertGetId(['travel_request_id'=>$travelId,'provider'=>$v['provider'],'booking_type'=>$v['bookingType'],'reference'=>$v['reference']??null,'cost'=>$v['cost'],'status'=>'PENDING','created_at'=>now(),'updated_at'=>now()]);return $this->ok(DB::table('travel_bookings')->find($id),201);}
    public function bookingStatus(Request $r,$id){$v=$r->validate(['status'=>['required',Rule::in(['PENDING','CONFIRMED','CANCELLED'])]]);DB::table('travel_bookings')->where('id',$id)->update(['status'=>$v['status'],'updated_at'=>now()]);return $this->ok(DB::table('travel_bookings')->find($id));}
    public function pendingBookings(){return $this->ok(DB::table('travel_requests as t')->leftJoin('travel_bookings as b','t.id','=','b.travel_request_id')->where('t.status','APPROVED')->whereNull('b.id')->select('t.*')->get());}

    public function approvalsPending(Request $r){return $this->ok(DB::table('approvals')->where('approver_id',$r->user()->id)->where('status','PENDING')->get());}
    public function approvalTimeline(Request $r,$travelId){$t=DB::table('travel_requests')->find($travelId);if(!$this->ownsTravel($r,$t))return $this->fail('Tidak memiliki akses',403);return $this->ok(DB::table('approvals')->where('travel_request_id',$travelId)->orderBy('level')->get());}
    public function approvalDecision(Request $r,$id){$v=$r->validate(['status'=>['required',Rule::in(['APPROVED','REJECTED'])],'note'=>'nullable|string']);$a=DB::table('approvals')->find($id);if(!$a||($a->approver_id!=$r->user()->id && $this->role($r)!=='SUPER_ADMIN'))return $this->fail('Approval tidak ditemukan atau bukan milik approver',403);if($a->status!=='PENDING')return $this->fail('Approval sudah diproses',409);DB::transaction(function()use($a,$v){DB::table('approvals')->where('id',$a->id)->update(['status'=>$v['status'],'note'=>$v['note']??null,'updated_at'=>now()]);$remaining=DB::table('approvals')->where('travel_request_id',$a->travel_request_id)->where('status','PENDING')->count();if($v['status']==='REJECTED')DB::table('travel_requests')->where('id',$a->travel_request_id)->update(['status'=>'REJECTED','updated_at'=>now()]);elseif(!$remaining)DB::table('travel_requests')->where('id',$a->travel_request_id)->update(['status'=>'APPROVED','updated_at'=>now()]);});return $this->ok(DB::table('approvals')->find($id));}
    public function delegationCreate(Request $r){$v=$r->validate(['delegateId'=>'required|exists:users,id','startDate'=>'required|date','endDate'=>'required|date|after_or_equal:startDate','reason'=>'required|string']);$id=DB::table('delegations')->insertGetId(['delegator_id'=>$r->user()->id,'delegate_id'=>$v['delegateId'],'start_date'=>$v['startDate'],'end_date'=>$v['endDate'],'reason'=>$v['reason'],'created_at'=>now(),'updated_at'=>now()]);return $this->ok(DB::table('delegations')->find($id),201);}
    public function delegationsIndex(Request $r){return $this->ok(DB::table('delegations')->where(fn($q)=>$q->where('delegator_id',$r->user()->id)->orWhere('delegate_id',$r->user()->id))->get());}
    public function delegationDelete(Request $r,$id){$d=DB::table('delegations')->find($id);if(!$d||$d->delegator_id!=$r->user()->id)return $this->fail('Delegasi tidak ditemukan atau bukan milik Anda',403);if($d->start_date<=now()->toDateString())return $this->fail('Delegasi aktif/telah dimulai tidak dapat dibatalkan',409);DB::table('delegations')->where('id',$id)->delete();return $this->ok(['message'=>'Delegasi dibatalkan']);}

    public function reimbursementCreate(Request $r){$v=$r->validate(['travelId'=>'required|exists:travel_requests,id','advanceAmount'=>'nullable|numeric|min:0']);$t=DB::table('travel_requests')->find($v['travelId']);if(!$t||$t->user_id!=$r->user()->id||$t->status!=='COMPLETED')return $this->fail('Hanya pemilik travel berstatus COMPLETED yang dapat membuat reimbursement',403);$id=DB::table('reimbursements')->insertGetId(['travel_request_id'=>$t->id,'user_id'=>$r->user()->id,'advance_amount'=>$v['advanceAmount']??0,'approved_amount'=>null,'difference_amount'=>null,'status'=>'DRAFT','external_journal_ref'=>null,'created_at'=>now(),'updated_at'=>now()]);return $this->ok(DB::table('reimbursements')->find($id),201);}
    public function reimbursementsIndex(Request $r){$q=DB::table('reimbursements');if($this->role($r)!=='FINANCE')$q->where('user_id',$r->user()->id);if($r->filled('status'))$q->where('status',$r->status);return $this->ok($q->get());}
    public function reimbursementShow(Request $r,$id){$h=DB::table('reimbursements')->find($id);if(!$h||($h->user_id!=$r->user()->id&&!in_array($this->role($r),['FINANCE','ADMIN','SUPER_ADMIN'],true)))return $this->fail('Reimbursement tidak ditemukan atau tidak memiliki akses',404);return $this->ok(['reimbursement'=>$h,'items'=>DB::table('reimbursement_items')->where('reimbursement_id',$id)->get()]);}
    public function reimbursementItemCreate(Request $r,$id){$h=DB::table('reimbursements')->find($id);if(!$h||$h->user_id!=$r->user()->id)return $this->fail('Tidak memiliki akses',403);if($h->status!=='DRAFT')return $this->fail('Item hanya dapat ditambahkan saat DRAFT',409);$v=$r->validate(['category'=>['required',Rule::in(['TRANSPORT','HOTEL','MEAL','FLIGHT','OTHER'])],'description'=>'required|string','amount'=>'required|numeric|min:0','transactionDate'=>'required|date','receipt'=>'nullable|file|max:10240']);$path=$r->hasFile('receipt')?$r->file('receipt')->store('receipts'):null;$item=DB::table('reimbursement_items')->insertGetId(['reimbursement_id'=>$id,'category'=>$v['category'],'description'=>$v['description'],'amount'=>$v['amount'],'transaction_date'=>$v['transactionDate'],'receipt_path'=>$path,'created_at'=>now(),'updated_at'=>now()]);return $this->ok(DB::table('reimbursement_items')->find($item),201);}
    public function reimbursementItemDelete(Request $r,$itemId){$i=DB::table('reimbursement_items')->find($itemId);$h=$i?DB::table('reimbursements')->find($i->reimbursement_id):null;if(!$i||!$h||$h->user_id!=$r->user()->id)return $this->fail('Item tidak ditemukan atau tidak memiliki akses',403);if($h->status!=='DRAFT')return $this->fail('Item hanya dapat dihapus saat DRAFT',409);if($i->receipt_path)Storage::delete($i->receipt_path);DB::table('reimbursement_items')->where('id',$itemId)->delete();return $this->ok(['message'=>'Item dihapus']);}
    public function reimbursementSubmit(Request $r,$id){$h=DB::table('reimbursements')->find($id);if(!$h||$h->user_id!=$r->user()->id)return $this->fail('Tidak memiliki akses',403);if($h->status!=='DRAFT')return $this->fail('Hanya DRAFT yang dapat disubmit',409);DB::table('reimbursements')->where('id',$id)->update(['status'=>'SUBMITTED','updated_at'=>now()]);return $this->ok(DB::table('reimbursements')->find($id));}
    public function reimbursementVerify(Request $r,$id){$v=$r->validate(['approvedAmount'=>'required|numeric|min:0','status'=>['required',Rule::in(['APPROVED','REJECTED'])],'note'=>'nullable|string']);$h=DB::table('reimbursements')->find($id);if(!$h||$h->status!=='SUBMITTED')return $this->fail('Reimbursement harus SUBMITTED',409);$diff=$v['approvedAmount']-(float)$h->advance_amount;DB::table('reimbursements')->where('id',$id)->update(['approved_amount'=>$v['approvedAmount'],'difference_amount'=>$diff,'status'=>$v['status'],'finance_note'=>$v['note']??null,'updated_at'=>now()]);return $this->ok(DB::table('reimbursements')->find($id));}
    public function reimbursementPay(Request $r,$id){$v=$r->validate(['externalJournalRef'=>'required|string|max:255']);$h=DB::table('reimbursements')->find($id);if(!$h||$h->status!=='APPROVED')return $this->fail('Hanya reimbursement APPROVED yang dapat dibayar',409);DB::table('reimbursements')->where('id',$id)->update(['status'=>'PAID','external_journal_ref'=>$v['externalJournalRef'],'updated_at'=>now()]);return $this->ok(DB::table('reimbursements')->find($id));}

    public function notificationsIndex(Request $r){$q=DB::table('notifications')->where('user_id',$r->user()->id);if($r->has('isRead'))$q->where('is_read',$r->boolean('isRead'));return $this->ok($q->orderByDesc('created_at')->get());}
    public function notificationRead(Request $r,$id){$n=DB::table('notifications')->where('id',$id)->where('user_id',$r->user()->id)->first();if(!$n)return $this->fail('Notifikasi tidak ditemukan',404);DB::table('notifications')->where('id',$id)->update(['is_read'=>true,'updated_at'=>now()]);return $this->ok(['message'=>'Notifikasi dibaca']);}
    public function notificationsReadAll(Request $r){DB::table('notifications')->where('user_id',$r->user()->id)->where('is_read',false)->update(['is_read'=>true,'updated_at'=>now()]);return $this->ok(['message'=>'Semua notifikasi ditandai dibaca']);}
    public function unreadCount(Request $r){return $this->ok(['count'=>DB::table('notifications')->where('user_id',$r->user()->id)->where('is_read',false)->count()]);}

    public function reportDashboard(){return $this->ok(['byStatus'=>DB::table('travel_requests')->select('status',DB::raw('COUNT(*) as total'))->groupBy('status')->get()]);}
    public function expenseByDepartment(Request $r){$q=DB::table('reimbursements as r')->join('users as u','r.user_id','=','u.id')->leftJoin('departments as d','u.department_id','=','d.id')->whereIn('r.status',['APPROVED','PAID']);if($r->filled('startDate'))$q->whereDate('r.updated_at','>=',$r->startDate);if($r->filled('endDate'))$q->whereDate('r.updated_at','<=',$r->endDate);return $this->ok($q->groupBy('d.id','d.name')->select('d.id','d.name as department',DB::raw('SUM(r.approved_amount) as totalExpense'))->get());}
    public function expenseByEmployee(Request $r){return $this->ok(DB::table('reimbursements as r')->join('users as u','r.user_id','=','u.id')->whereIn('r.status',['APPROVED','PAID'])->groupBy('u.id','u.name')->select('u.id','u.name as employee',DB::raw('SUM(r.approved_amount) as totalExpense'))->get());}
    public function expenseByProject(){return $this->ok(DB::table('travel_requests')->select('purpose as project',DB::raw('SUM(estimated_cost) as totalExpense'))->whereIn('status',['APPROVED','COMPLETED'])->groupBy('purpose')->get());}
    public function reportExport(Request $r){$r->validate(['format'=>'required|in:pdf,excel']);return $this->fail('Export belum diaktifkan. Pasang paket PDF/Excel dan implementasikan formatter sesuai kebutuhan bisnis.',501);}
}
